pipeline {
 agent none
 options { disableConcurrentBuilds(); skipDefaultCheckout(true); timeout(time: 60, unit: 'MINUTES') }
 environment {
  RELEASE_SOURCE_SHA = '5bf5c154475d9332ae8c2e8b35959c287bbfa3aecf6146c341768059077d0890'
  RELEASE_BASE_REVISION = '5056ccba9e75a891cc133a6f371b49deb5dbc598'
  IMAGE_TAG = 'ghcr.io/evodmik/robingraph:approved-no-audio-20261111-5bf5c154475d'
 }
 stages {
  stage('Verify scoped snapshot and publish AMD64') {
   agent { label 'robingraph-mac16' }
   environment { DOCKER_CONTEXT = 'orbstack'; PATH = '/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin' }
   steps {
    script { env.DOCKER_CONFIG = "${pwd(tmp: true)}/approved-registry-auth" }
    withCredentials([usernamePassword(credentialsId: 'robingraph-ghcr', usernameVariable: 'GHCR_USERNAME', passwordVariable: 'GHCR_TOKEN')]) {
     sh '''#!/bin/sh
set -eu
umask 077
mkdir -p "$DOCKER_CONFIG"
if [ -d "$HOME/.docker/cli-plugins" ]; then ln -s "$HOME/.docker/cli-plugins" "$DOCKER_CONFIG/cli-plugins"; fi
DOCKER_CONFIG="$HOME/.docker" docker context export orbstack - | env -u DOCKER_CONTEXT docker context import orbstack -
python3 - <<'CHECK'
from pathlib import Path
import json,hashlib
w=Path('/tmp/robingraph-approved-prod-20261111');m=json.loads((w/'candidate-manifest.json').read_text());assert m['source_sha256']=='5bf5c154475d9332ae8c2e8b35959c287bbfa3aecf6146c341768059077d0890'
for name,digest in m['files'].items():assert hashlib.sha256((w/'candidate'/name).read_bytes()).hexdigest()==digest,name
assert not list((w/'candidate/src').rglob('*audio*'))
CHECK
cd /tmp/robingraph-approved-prod-20261111/candidate
PYTHONPATH=src:tests /Volumes/OrcaRoot/orca/workspaces/RobinGraph/dev-codex/.venv/bin/python -m django check --settings=robingraph.django_api.settings
PYTHONPATH=src:tests /Volumes/OrcaRoot/orca/workspaces/RobinGraph/dev-codex/.venv/bin/python -m unittest tests.test_bird_explorer tests.test_taxon_traits tests.test_graph_followup tests.test_graph_questions_api tests.test_drf_parity tests.test_api tests.test_external_cache tests.test_species_notes tests.test_chat_feedback tests.test_chat_clarification tests.test_species_profile -q
node --test --test-skip-pattern=recording tests/frontend/chat_ui.test.js tests/frontend/birds_ui.test.js tests/frontend/explore_ui.test.js
printf '%s\n' "$GHCR_TOKEN" | docker login ghcr.io --username "$GHCR_USERNAME" --password-stdin
docker buildx build --platform linux/amd64 --push --build-arg "VCS_REF=$RELEASE_BASE_REVISION" --label "org.robingraph.source.sha256=$RELEASE_SOURCE_SHA" --tag "$IMAGE_TAG" --metadata-file "$WORKSPACE/image-metadata.json" .
'''
    }
    script {
     env.IMMUTABLE_IMAGE = sh(script: '''python3 -c 'import json; print("ghcr.io/evodmik/robingraph@"+json.load(open("image-metadata.json"))["containerimage.digest"])' ''',returnStdout:true).trim()
    }
    sh '''#!/bin/sh
set -eu
name="robingraph-approved-amd64-$BUILD_NUMBER"
cleanup() { docker rm -f "$name" >/dev/null 2>&1 || true; }
trap cleanup EXIT HUP INT TERM
docker run -d --platform linux/amd64 --name "$name" --network none --read-only --tmpfs /tmp "$IMMUTABLE_IMAGE" robingraph serve-fixture --host 0.0.0.0 --port 8000
attempt=0
until docker exec "$name" python -c 'import json,urllib.request; d=json.load(urllib.request.urlopen("http://127.0.0.1:8000/health",timeout=3)); assert d["status"]=="ok"; s=json.load(urllib.request.urlopen("http://127.0.0.1:8000/openapi.json",timeout=3)); assert "/v1/taxa/explore" in s["paths"]; assert not any("audio" in p for p in s["paths"])' >/dev/null 2>&1; do
 attempt=$((attempt+1)); if [ "$attempt" -ge 45 ]; then exit 1; fi; sleep 2
done
cp /tmp/robingraph-approved-prod-20261111/candidate/scripts/deploy_registry_prod.py deploy_registry_prod.py
python3 -c "import base64;from pathlib import Path;Path('nas_release.py').write_bytes(base64.b64decode(''));Path('verify_release.py').write_bytes(base64.b64decode(''))"

'''
    stash name: 'approved-non-audio-helper', includes: 'deploy_registry_prod.py,nas_release.py,verify_release.py'
    archiveArtifacts artifacts: 'image-metadata.json'
   }
   post { always { sh 'docker logout ghcr.io >/dev/null 2>&1 || true' } }
  }
  stage('Read-only candidate against Production data') {
   agent { label 'robingraph-nas-deploy' }
   environment { DOCKER_CONTEXT = 'default'; DOCKER_HOST = 'unix:///var/run/docker.sock'; RELEASE_ACTION = 'preflight' }
   steps {
    unstash 'approved-non-audio-helper'
    withCredentials([usernamePassword(credentialsId:'robingraph-ghcr',usernameVariable:'GHCR_USERNAME',passwordVariable:'GHCR_TOKEN')]) { sh 'python3 nas_release.py' }
    stash name:'approved-candidate-report', includes:'production-candidate.json'
    archiveArtifacts artifacts:'production-candidate.json'
   }
  }
  stage('Authorized non-audio Production approval') {
   steps {
    input(id:'approveNonAudioProduction',submitter:'admin',ok:'Deploy approved non-audio snapshot',message:"Deploy user-approved non-audio source ${env.RELEASE_SOURCE_SHA}, image ${env.IMMUTABLE_IMAGE}; preserve DBs, runtime and TEST?")
   }
  }
  stage('Deploy and verify Production app') {
   agent { label 'robingraph-nas-deploy' }
   environment { DOCKER_CONTEXT='default'; DOCKER_HOST='unix:///var/run/docker.sock'; RELEASE_ACTION='deploy' }
   steps {
    unstash 'approved-non-audio-helper'; unstash 'approved-candidate-report'
    withCredentials([usernamePassword(credentialsId:'robingraph-ghcr',usernameVariable:'GHCR_USERNAME',passwordVariable:'GHCR_TOKEN')]) { sh 'python3 nas_release.py' }
   }
   post { always { archiveArtifacts artifacts:'production-release.json,production-live.json', allowEmptyArchive:true } }
  }
 }
}
